const run = $('Init Run').first().json;
const body = $input.first().json;
let text = '';
if (body.content && body.content[0]?.text) text = body.content[0].text;
else if (typeof body === 'string') text = body;
else text = JSON.stringify(body);
const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
const candidate = (fenced?.[1] ?? text).trim();
const start = candidate.indexOf('{');
const end = candidate.lastIndexOf('}');
if (start < 0 || end <= start) throw new Error('Writer: no JSON in Claude response');
const pack = JSON.parse(candidate.slice(start, end + 1));
pack.brand = 'alpha';
pack.topic = run.topic;
pack.run_id = run.run_id;
if (!Array.isArray(pack.x_thread)) {
  if (typeof pack.x_thread === 'string') pack.x_thread = pack.x_thread.split(/\n+/).filter(Boolean);
  else pack.x_thread = [];
}
const banned = [/vào long/i, /vào short/i, /entry/i, /\bSL\b/i, /\bTP\b/i, /chắc ăn/i, /guaranteed/i];
const failed = [];
if (banned.some((r) => (pack.telegram_brief || '').match(r) || pack.x_thread.some((t) => t.match(r)))) failed.push(1);
for (const t of pack.x_thread) { if (t.length > 280) failed.push(4); if (/https?:\/\//i.test(t)) failed.push(4); }
if ((pack.threads_post || '').length > 500) failed.push(4);
pack.compliance = { status: failed.length ? 'FAIL' : 'PASS', failed_rules: [...new Set(failed)] };
return [{ json: { ...run, pack, writer_output_file: `output/alpha/${run.date}/${run.run_id}.pack.json` } }];

