const prev = $('Parse Pack').first().json;
const body = $input.first().json.body ?? $input.first().json;
const approved = body.approved === true || /OK đăng|OK dang|duyệt|dang/i.test(String(body.reply_text || body.text || ''));
const mediaId = body.media_id || body.mediaId || (String(body.reply_text || '').match(/mediaId[:\s]+([\w-]+)/i)?.[1]);
if (!approved) throw new Error('Not approved');
return [{ json: { ...prev, status: 'approved', approved_at: new Date().toISOString(), media: { mode: 'manual_mediaId', media_id: mediaId || null } } }];

const ctx = $('Parse Approval').first().json;
const z = $input.first().json;
const postId = z.id || z.postId || z.data?.id || null;
const publish = {
  agent: 'n8n-zernio',
  zernio_post_id: postId,
  raw: z,
  x_url: postId ? `https://x.com/AlphaTrading79/status/${postId}` : null,
  threads_url: null,
  output_file: `output/alpha/${ctx.date}/${ctx.run_id}.publish.json`
};
const run = {
  run_id: ctx.run_id,
  brand: 'alpha',
  topic: ctx.topic,
  status: postId ? 'published' : 'failed',
  created_at: ctx.created_at,
  updated_at: new Date().toISOString(),
  stages: {
    writer: { agent: 'n8n-writer', model: 'claude-sonnet-4-20250514', output_file: ctx.writer_output_file },
    media: ctx.media,
    telegram: { agent: 'n8n-telegram', approved: true, approved_at: ctx.approved_at },
    publish,
  },
  pack: ctx.pack
};
return [{ json: run }];

